class PatchRefusal(RuntimeError):
    """A typed preparation refusal never grants native build or runtime authority."""

    def __init__(self, code, message):
        self.code = code
        super().__init__(message)


@dataclass(frozen=True, slots=True)
class SourceSeal:
    path: str
    mode: str
    git_oid: str
    sha256: str


@dataclass(frozen=True, slots=True)
class NamespaceReplacement:
    path: str
    original_sha256: str
    output_bytes: bytes


@dataclass(frozen=True, slots=True)
class NamespacePlan:
    source_root: str
    pins: tuple[tuple[str, str], ...]
    originals: tuple[tuple[str, str], ...]
    inventory: tuple[SourceSeal, ...]
    replacements: tuple[NamespaceReplacement, ...]


def _require(condition, code, message):
    if not condition:
        raise PatchRefusal(code, message)


def _deadline(absolute_deadline):
    try:
        finite = type(absolute_deadline) in {int, float} and math.isfinite(absolute_deadline)
    except OverflowError:
        finite = False
    _require(
        finite and time.monotonic() < absolute_deadline,
        "deadline",
        "The caller's finite absolute deadline expired or is invalid",
    )


def _replace(source, old, new, count=1):
    _require(source.count(old) == count, "preimage", "An exact transformation anchor changed")
    return source.replace(old, new)


def assemble_namespace(
    originals: Mapping[str, bytes], absolute_deadline: float
) -> dict[str, bytes]:
    """Transform only the five fixed original files; retain a private detached result."""
    _deadline(absolute_deadline)
    _require(isinstance(originals, Mapping), "missing", "Original inputs must be a path mapping")
    supplied = dict(originals)
    _deadline(absolute_deadline)
    expected = dict(PREIMAGES)
    _require(not expected.keys() - supplied.keys(), "missing", "A required original is missing")
    _require(
        not supplied.keys() - expected.keys(), "extra", "An input expands the owned source scope"
    )
    for path, wanted in PREIMAGES:
        _deadline(absolute_deadline)
        data = supplied[path]
        _require(
            type(data) is bytes and hashlib.sha256(data).hexdigest() == wanted,
            "preimage",
            "A fixed original preimage changed: " + path,
        )
    _deadline(absolute_deadline)
    output = dict(supplied)
    constants = supplied["src/share/constants.hpp"].decode("utf-8")
    for old, new, count in (
        (
            "/Library/Application Support/org.pqrs/tmp",
            "/Library/Application Support/ErgoptiPlus/RemapRuntime/tmp",
            4,
        ),
        (
            "/Library/Application Support/org.pqrs/config",
            "/Library/Application Support/ErgoptiPlus/RemapRuntime/config",
            1,
        ),
        ("karabiner_core_service_daemon.sock", "core.sock", 2),
        ("karabiner_console_user_id_changed_receiver.sock", "session.sock", 2),
        ("karabiner_console_user_server.sock", "console.sock", 2),
        ('"karabiner_machine_identifier.json"', '"machine_identifier.json"', 1),
        ('"karabiner_app_icon.json"', '"app_icon.json"', 1),
        ('"karabiner.json"', '"core.json"', 2),
        ('"karabiner_environment"', '"runtime_environment"', 1),
        ('directory /= "karabiner";', 'directory /= "ergoptiplus/remap-runtime";', 2),
        ("length is 76.", "length is 67.", 1),
        ("length is 89.", "length is 70.", 1),
        (
            '/user/501/console.sock" length is 85.',
            '/user/4294967295/console.sock" length is 86.',
            1,
        ),
    ):
        _deadline(absolute_deadline)
        constants = _replace(constants, old, new, count)
    output["src/share/constants.hpp"] = constants.encode("utf-8")
    path = "src/apps/CoreService/include/core_service/main/daemon.hpp"
    output[path] = _replace(
        supplied[path].decode("utf-8"),
        '"/var/log/karabiner/core_service.log"',
        '"/Library/Application Support/ErgoptiPlus/RemapRuntime/log/core.log"',
    ).encode("utf-8")
    for path, old_product, product, old_identifier, identifier in (
        (
            "src/apps/CoreService/project.yml",
            "Karabiner-Core-Service",
            "ErgoptiPlus-Remap-Core",
            "org.pqrs.Karabiner-Core-Service",
            OWNED_CORE_BUNDLE_IDENTIFIER,
        ),
        (
            "src/apps/ConsoleUserServer/project.yml",
            "Karabiner-Console-User-Server",
            "ErgoptiPlus-Remap-Console",
            "org.pqrs.Karabiner-Console-User-Server",
            OWNED_CONSOLE_BUNDLE_IDENTIFIER,
        ),
        (
            "src/bin/cli/project.yml",
            "karabiner_cli",
            "ergoptiplus_remap_cli",
            None,
            OWNED_CLI_BUNDLE_IDENTIFIER,
        ),
    ):
        _deadline(absolute_deadline)
        recipe = supplied[path].decode("utf-8")
        recipe = _replace(recipe, "name: " + old_product + "\n", "name: " + product + "\n")
        recipe = _replace(recipe, "  " + old_product + ":\n", "  " + product + ":\n")
        if old_identifier is None:
            recipe = _replace(
                recipe,
                "    settings:\n",
                "    settings:\n      PRODUCT_BUNDLE_IDENTIFIER: " + identifier + "\n",
            )
        else:
            recipe = _replace(
                recipe,
                "PRODUCT_BUNDLE_IDENTIFIER: " + old_identifier,
                "PRODUCT_BUNDLE_IDENTIFIER: " + identifier,
            )
        output[path] = recipe.encode("utf-8")
    _deadline(absolute_deadline)
    return output


def _git(root, args, absolute_deadline):
    _deadline(absolute_deadline)
    environment = dict(os.environ, GIT_OPTIONAL_LOCKS="0", GIT_TERMINAL_PROMPT="0")
    for key in (
        "GIT_DIR",
        "GIT_WORK_TREE",
        "GIT_COMMON_DIR",
        "GIT_INDEX_FILE",
        "GIT_OBJECT_DIRECTORY",
        "GIT_ALTERNATE_OBJECT_DIRECTORIES",
        "GIT_NAMESPACE",
        "GIT_CONFIG_PARAMETERS",
        "GIT_CONFIG_COUNT",
    ):
        environment.pop(key, None)
    try:
        result = subprocess.run(
            ["git", "--no-optional-locks", "-C", str(root), "-c", "core.fsmonitor=false", *args],
            env=environment,
            capture_output=True,
            timeout=absolute_deadline - time.monotonic(),
            check=False,
        )
    except subprocess.TimeoutExpired as error:
        raise PatchRefusal(
            "deadline", "A source inspection exceeded the caller's deadline"
        ) from error
    except OSError as error:
        raise PatchRefusal("pin", "The actual Git source is unavailable") from error
    _deadline(absolute_deadline)
    _require(result.returncode == 0, "pin", "A pinned Git source inspection failed")
    return result.stdout


def _canonical_directory(path):
    try:
        info = path.lstat()
        canonical = path.resolve(strict=True)
    except (OSError, RuntimeError) as error:
        raise PatchRefusal("unsafe_path", "Source directory is unavailable") from error
    _require(
        path.is_absolute() and canonical == path and stat.S_ISDIR(info.st_mode),
        "unsafe_path",
        "Source directory must be ordinary and canonical",
    )


def _read_original(path, absolute_deadline):
    _deadline(absolute_deadline)
    try:
        fd = os.open(path, os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
        with os.fdopen(fd, "rb") as stream:
            before = os.fstat(stream.fileno())
            _require(
                stat.S_ISREG(before.st_mode) and before.st_size <= MAX_SOURCE_BYTES,
                "unsafe_path",
                "Source input is not a bounded ordinary file",
            )
            data = stream.read(MAX_SOURCE_BYTES + 1)
            after = os.fstat(stream.fileno())
            _require(
                (
                    before.st_dev,
                    before.st_ino,
                    before.st_size,
                    before.st_mtime_ns,
                    before.st_ctime_ns,
                )
                == (after.st_dev, after.st_ino, after.st_size, after.st_mtime_ns, after.st_ctime_ns)
                and len(data) == after.st_size,
                "source_changed",
                "Source changed while reading",
            )
    except OSError as error:
        raise PatchRefusal("unsafe_path", "Source input is unavailable or redirected") from error
    _deadline(absolute_deadline)
    return (data, after)


def _inventory(root, relative, pin, absolute_deadline):
    """Compare each actual tracked leaf to the pinned Git object, including gitlinks."""
    _canonical_directory(root)
    _require(
        _git(root, ["rev-parse", "HEAD"], absolute_deadline).decode().strip() == pin,
        "pin",
        "The actual source checkout is at another commit",
    )
    _require(
        not _git(
            root,
            ["status", "--porcelain=v1", "--untracked-files=all", "--ignored"],
            absolute_deadline,
        ),
        "inventory",
        "Source has changed, untracked or ignored inputs",
    )
    tree = _git(root, ["ls-tree", "-r", "-z", pin], absolute_deadline)
    seals = []
    for entry in tree.split(b"\x00"):
        if not entry:
            continue
        _deadline(absolute_deadline)
        metadata, raw_path = entry.split(b"\t", 1)
        mode, kind, oid = metadata.decode("ascii").split(" ")
        name = raw_path.decode("utf-8")
        path = root / name
        full = (relative / name).as_posix()
        _require(
            not path.is_absolute() or path.is_relative_to(root),
            "inventory",
            "Source path escapes its checkout",
        )
        _require(
            path.parent.resolve(strict=True) == path.parent,
            "unsafe_path",
            "Source ancestor redirects",
        )
        if mode == "160000" and kind == "commit":
            _require(oid in {CPM, VHD}, "pin", "Unknown source submodule pin")
            seals.append(
                SourceSeal(full, mode, oid, hashlib.sha256(oid.encode("ascii")).hexdigest())
            )
            seals.extend(_inventory(path, relative / name, oid, absolute_deadline))
            continue
        _require(
            kind == "blob" and mode in {"100644", "100755", "120000"},
            "inventory",
            "Unknown pinned source leaf mode",
        )
        if mode == "120000":
            _require(path.is_symlink(), "inventory", "Pinned source link was replaced")
            data = os.fsencode(os.readlink(path))
        else:
            data, info = _read_original(path, absolute_deadline)
            _require(
                bool(info.st_mode & 73) == (mode == "100755"),
                "inventory",
                "Pinned source executable mode changed",
            )
        object_bytes = b"blob " + str(len(data)).encode("ascii") + b"\x00" + data
        _require(
            hashlib.sha1(object_bytes).hexdigest() == oid,
            "inventory",
            "Actual source leaf differs from its pin: " + full,
        )
        seals.append(SourceSeal(full, mode, oid, hashlib.sha256(data).hexdigest()))
    _deadline(absolute_deadline)
    return tuple(seals)


def plan_namespace(source_root: Path, absolute_deadline: float) -> NamespacePlan:
    """Seal a genuine complete checkout and produce immutable outputs without writes."""
    _deadline(absolute_deadline)
    root = Path(source_root)
    _canonical_directory(root)
    before = _inventory(root, Path(), UPSTREAM, absolute_deadline)
    originals = {path: _read_original(root / path, absolute_deadline)[0] for path, _ in PREIMAGES}
    output = assemble_namespace(originals, absolute_deadline)
    after = _inventory(root, Path(), UPSTREAM, absolute_deadline)
    _require(
        before == after, "source_changed", "The pinned source inventory changed during planning"
    )
    _deadline(absolute_deadline)
    return NamespacePlan(
        str(root),
        (("upstream", UPSTREAM), ("cpm", CPM), ("vhd", VHD)),
        PREIMAGES,
        after,
        tuple((NamespaceReplacement(path, wanted, output[path]) for path, wanted in PREIMAGES)),
    )


