def render_identity_header(absolute_deadline: float) -> bytes:
    """Render fixed source identifiers; this never qualifies a native signed role."""
    _deadline(absolute_deadline)
    output = [
        "#pragma once\n\n",
        "// Fixed source policy only. Native signed-role acquisition is separate.\n",
        "#include <cstdint>\n#include <string_view>\n\n",
        "namespace ergoptiplus::remap::identity {\n\n",
        "enum class role : std::uint8_t { unavailable, core, console, cli };\n\n",
        "[[nodiscard]] constexpr std::string_view identifier(role value) noexcept {\n",
        "  switch (value) {\n",
    ]
    for role, identifier in OWNED_PRODUCT_IDENTIFIERS:
        _deadline(absolute_deadline)
        output.append(f'    case role::{role}: return "{identifier}";\n')
    output.extend(
        [
            "    default: return {};\n  }\n}\n\n",
            "[[nodiscard]] constexpr role classify(std::string_view value) noexcept {\n",
        ]
    )
    for role, _ in OWNED_PRODUCT_IDENTIFIERS:
        _deadline(absolute_deadline)
        output.append(f"  if (value == identifier(role::{role})) {{ return role::{role}; }}\n")
    output.append("  return role::unavailable;\n}\n\n} // namespace ergoptiplus::remap::identity\n")
    data = "".join(output).encode("utf-8")
    _deadline(absolute_deadline)
    return data


