        "typedef void (*console_user_server_terminated_callback)(void);\n\n",
        "typedef void (*console_user_server_terminated_callback)(void);\n\ntypedef void (*console_user_server_owner_exit_callback)(void);\n\ntypedef enum console_user_server_owner_phase {\n  console_user_server_owner_unavailable,\n  console_user_server_owner_preparing,\n  console_user_server_owner_active,\n  console_user_server_owner_retiring,\n  console_user_server_owner_tainted\n} console_user_server_owner_phase;\n\ntypedef enum console_user_server_owner_refusal {\n  console_user_server_owner_no_refusal,\n  console_user_server_owner_invalid_thread,\n  console_user_server_owner_generation_exhausted,\n  console_user_server_owner_acquisition_failed,\n  console_user_server_owner_native_refused,\n  console_user_server_owner_retirement_failed,\n  console_user_server_owner_queue_failed,\n  console_user_server_owner_callback_failed\n} console_user_server_owner_refusal;\n\n// Diagnostic bookkeeping only, never native readiness or a retirement ACK.\nconsole_user_server_owner_phase console_user_server_owner_status(void);\nconsole_user_server_owner_refusal console_user_server_owner_last_refusal(void);\nbool console_user_server_start_owner_watch(console_user_server_owner_exit_callback callback);\n\n",
