def assemble_current_framework_retirement(
    inputs: Mapping[str, bytes], absolute_deadline: float
) -> dict[str, bytes]:
    """Emit exact selected cleanup admission/retention; prior profiles remain exact."""
    _deadline(absolute_deadline)
    _require(isinstance(inputs, Mapping), "missing", "Cleanup inputs must be a mapping")
    supplied = dict(inputs)
    expected = dict(AUTH_CLEANUP_TRANSPORT_PREIMAGES)
    _require(not expected.keys() - supplied.keys(), "missing", "Cleanup input missing")
    _require(not supplied.keys() - expected.keys(), "extra", "Cleanup scope expanded")
    for path, wanted in expected.items():
        _deadline(absolute_deadline)
        _require(
            type(supplied[path]) is bytes and hashlib.sha256(supplied[path]).hexdigest() == wanted,
            "preimage",
            "Actual selected cleanup preimage changed",
        )
