AUTH_RECIPE_PREIMAGES = (
    (
        "src/apps/ConsoleUserServer/project.yml",
        "090cda2272b7b328a6226f0877d416da602043a627ec1eb212867e6056bf0e55",
    ),
    (
        "src/apps/CoreService/project.yml",
        "5434a41f9f425189b815819e5194cbd240392b15fa73e7e88d34b35698f5b871",
    ),
    ("src/bin/cli/project.yml", "939904fd7da0838fb50181b4a38147c25be3a3fda066a4c32fb60594ff2ea4b2"),
)


def assemble_auth_link_dependencies(
    project_recipes: Mapping[str, bytes], absolute_deadline: float
) -> dict[str, bytes]:
    """Add fixed native SDK links to released owned recipes, with no I/O."""
    _deadline(absolute_deadline)
    _require(isinstance(project_recipes, Mapping), "missing", "Recipes must be a mapping")
    supplied = dict(project_recipes)
    expected = dict(AUTH_RECIPE_PREIMAGES)
    _require(not expected.keys() - supplied.keys(), "missing", "An owned recipe is missing")
    _require(not supplied.keys() - expected.keys(), "extra", "An input expands owned recipes")
    output = {}
    for path, wanted in expected.items():
        _deadline(absolute_deadline)
        data = supplied[path]
        _require(
            type(data) is bytes and hashlib.sha256(data).hexdigest() == wanted,
            "preimage",
            "An owned recipe drifts from released output",
        )
        text = data.decode("utf-8")
        if "    dependencies:\n" not in text:
            _require(
                path == "src/bin/cli/project.yml", "preimage", "Expected dependency list is missing"
            )
            text += "    dependencies:\n"
        text += "      - sdk: Security.framework\n"
        text = _replace(
            text,
            "      OTHER_LDFLAGS:\n        - ../../../vendor/duktape-src/build/Release/libduktape.a\n",
            "      OTHER_LDFLAGS:\n        - $(inherited)\n        - ../../../vendor/duktape-src/build/Release/libduktape.a\n        - -lbsm\n",
        )
        output[path] = text.encode("utf-8")
    _deadline(absolute_deadline)
    return output
